class Provider {
    constructor() {
        this.api = "https://hentaiera.com";
        this.cache = {};
        this.providerMapKey = "hentaiera.provider.map";
        this.customSourceMapKey = "hentaiera";
    }

    getSettings() {
        return {
            supportsMultiLanguage: true,
            supportsMultiScanlator: false,
        };
    }

    async search(opts) {
        var query = String((opts && opts.query) || "").trim();

        if (!query) {
            return await this.getLatest();
        }

        var mappedUrl = this.lookupStoredUrl(query);

        if (mappedUrl) {
            var mappedResult = await this.resultFromGalleryUrl(mappedUrl);
            return mappedResult ? [mappedResult] : [];
        }

        if (query.indexOf("hentaiera.com") >= 0 && query.indexOf("/gallery/") >= 0) {
            var direct = await this.resultFromGalleryUrl(query);
            return direct ? [direct] : [];
        }

        var directId = this.getGalleryId(query);

        if (directId && this.looksLikeGalleryId(directId)) {
            var directUrl = this.api + "/gallery/" + directId + "/";
            var directResult = await this.resultFromGalleryUrl(directUrl);

            if (directResult) {
                return [directResult];
            }
        }

        var titleMapped = this.lookupTitleUrl(query);

        if (titleMapped) {
            var titleMappedResult = await this.resultFromGalleryUrl(titleMapped);
            return titleMappedResult ? [titleMappedResult] : [];
        }

        var urls = [
            this.api + "/?s=" + encodeURIComponent(query),
            this.api + "/?q=" + encodeURIComponent(query),
            this.api + "/?search=" + encodeURIComponent(query),
            this.api + "/search/" + encodeURIComponent(this.slugify(query)) + "/",
            this.api + "/search?query=" + encodeURIComponent(query),
            this.api + "/search?q=" + encodeURIComponent(query)
        ];

        var all = [];
        var seen = {};

        for (var i = 0; i < urls.length; i++) {
            try {
                var html = await this.fetchText(urls[i]);

                if (!html || html.length < 300) {
                    continue;
                }

                var results = this.parseSearchResults(html);

                for (var j = 0; j < results.length; j++) {
                    var item = results[j];

                    if (!item || !item.id || seen[item.id]) {
                        continue;
                    }

                    seen[item.id] = true;

                    var hydrated = await this.resultFromGalleryUrl(item.id);

                    if (!hydrated || !hydrated.title) {
                        continue;
                    }

                    if (this.isBlockedText(hydrated.title)) {
                        continue;
                    }

                    var score = this.searchScore(query, hydrated.title, hydrated.id);

                    if (score < 40) {
                        continue;
                    }

                    hydrated._score = score;
                    all.push(hydrated);
                    this.storeMapping(hydrated.id, hydrated.title);
                }
            } catch (err) {
                console.error("hentaiera search failed: " + String(err));
            }
        }

        all.sort(function (a, b) {
            return (b._score || 0) - (a._score || 0);
        });

        for (var x = 0; x < all.length; x++) {
            delete all[x]._score;
        }

        return all.slice(0, 30);
    }

    async findChapters(mangaId) {
        var url = await this.resolveToGalleryUrl(mangaId);

        if (!url) {
            return [];
        }

        try {
            var html = await this.fetchText(url);

            if (!html || html.length < 300) {
                return [];
            }

            var title = this.getGalleryTitle(html, url);
            var language = this.getGalleryLanguage(html);

            if (this.isBlockedText(title) || this.hasBlockedTags(html)) {
                return [];
            }

            this.storeMapping(url, title);

            return [{
                id: url,
                url: url,
                title: title || "Full Gallery",
                chapter: "1",
                index: 0,
                language: language || "en",
            }];
        } catch (err) {
            console.error("hentaiera findChapters failed: " + String(err));
            return [];
        }
    }

    async findChapterPages(chapterId) {
        var url = await this.resolveToGalleryUrl(chapterId);

        if (!url) {
            return [];
        }

        try {
            var html = await this.fetchText(url);

            if (!html || html.length < 300) {
                return [];
            }

            if (this.hasBlockedTags(html)) {
                return [];
            }

            var images = this.parseGalleryImages(html);

            console.log("hentaiera pages found: " + images.length);

            var pages = [];

            for (var i = 0; i < images.length; i++) {
                pages.push({
                    url: images[i],
                    index: i,
                    headers: {
                        Referer: url,
                        Origin: this.api,
                        "User-Agent": "Mozilla/5.0",
                    },
                });
            }

            return pages;
        } catch (err) {
            console.error("hentaiera findChapterPages failed: " + String(err));
            return [];
        }
    }

    async getLatest() {
        var urls = [
            this.api + "/",
            this.api + "/page/1/"
        ];

        for (var u = 0; u < urls.length; u++) {
            try {
                var html = await this.fetchText(urls[u]);
                var results = this.parseSearchResults(html);
                var out = [];
                var seen = {};

                for (var i = 0; i < results.length; i++) {
                    if (!results[i] || !results[i].id || seen[results[i].id]) {
                        continue;
                    }

                    seen[results[i].id] = true;

                    var hydrated = await this.resultFromGalleryUrl(results[i].id);

                    if (!hydrated || !hydrated.title) {
                        continue;
                    }

                    if (this.isBlockedText(hydrated.title)) {
                        continue;
                    }

                    this.storeMapping(hydrated.id, hydrated.title);
                    out.push(hydrated);

                    if (out.length >= 30) {
                        break;
                    }
                }

                if (out.length > 0) {
                    return out;
                }
            } catch (err) {
                console.error("hentaiera latest failed: " + String(err));
            }
        }

        return [];
    }

    async resultFromGalleryUrl(url) {
        url = this.normalizeGalleryUrl(url);

        if (!url) {
            return null;
        }

        try {
            var html = await this.fetchText(url);

            if (!html || html.length < 300) {
                return null;
            }

            var title = this.getGalleryTitle(html, url);

            if (this.isBlockedText(title) || this.hasBlockedTags(html)) {
                return null;
            }

            var image =
                this.firstMatch(html, /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) ||
                this.firstMatch(html, /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i) ||
                this.firstMatch(html, /<img[^>]+src=["']([^"']*\/cover\.(?:jpg|jpeg|png|webp))["']/i) ||
                this.firstMatch(html, /<img[^>]+src=["']([^"']*\/1t?\.(?:jpg|jpeg|png|webp))["']/i) ||
                "";

            var result = {
                id: url,
                title: title || this.titleFromUrl(url),
                synonyms: this.getSynonymsFromGallery(html),
                year: 1,
                image: this.normalizeUrl(image),
            };

            this.storeMapping(url, result.title);

            return result;
        } catch (err) {
            console.error("hentaiera resultFromGalleryUrl failed: " + String(err));
            return null;
        }
    }

    async resolveToGalleryUrl(input) {
        var value = String(input || "").trim();

        if (!value) {
            return "";
        }

        var stored = this.lookupStoredUrl(value);

        if (stored) {
            return this.normalizeGalleryUrl(stored);
        }

        if (value.indexOf("hentaiera.com") >= 0 && value.indexOf("/gallery/") >= 0) {
            return this.normalizeGalleryUrl(value);
        }

        var id = this.getGalleryId(value);

        if (id && this.looksLikeGalleryId(id)) {
            var directUrl = this.api + "/gallery/" + id + "/";
            var valid = await this.galleryUrlLooksValid(directUrl);

            if (valid) {
                return directUrl;
            }
        }

        var titleMapped = this.lookupTitleUrl(value);

        if (titleMapped) {
            return this.normalizeGalleryUrl(titleMapped);
        }

        var results = await this.search({ query: value });

        if (results && results.length > 0 && results[0].id) {
            return this.normalizeGalleryUrl(results[0].id);
        }

        return "";
    }

    async galleryUrlLooksValid(url) {
        try {
            var html = await this.fetchText(url);

            if (!html || html.length < 300) {
                return false;
            }

            var title = this.getGalleryTitle(html, url);

            if (!title || this.isBlockedText(title)) {
                return false;
            }

            return true;
        } catch (err) {
            return false;
        }
    }

    parseSearchResults(html) {
        var results = [];
        var seen = {};
        var self = this;

        try {
            var $ = LoadDoc(html);

            $("a[href*='/gallery/']").each(function (i, e) {
                var href = e.attr("href") || "";
                var fullUrl = self.normalizeGalleryUrl(href);

                if (!fullUrl || seen[fullUrl]) {
                    return;
                }

                var title =
                    e.attr("title") ||
                    e.find("img").attr("alt") ||
                    e.find("h1").first().text() ||
                    e.find("h2").first().text() ||
                    e.find("h3").first().text() ||
                    e.find("h4").first().text() ||
                    e.find(".gallery-title").first().text() ||
                    e.find(".post-title").first().text() ||
                    e.find(".entry-title").first().text() ||
                    e.find(".card-title").first().text() ||
                    e.find(".title").first().text() ||
                    e.find(".name").first().text() ||
                    e.find(".caption").first().text() ||
                    "";

                title = self.cleanSearchTitle(title);

                if (!title || self.titleLooksLikeTagBlob(title)) {
                    title = self.titleFromUrl(fullUrl);
                }

                if (self.isBlockedText(title)) {
                    return;
                }

                var image =
                    e.find("img").attr("data-src") ||
                    e.find("img").attr("data-original") ||
                    e.find("img").attr("data-lazy-src") ||
                    e.find("img").attr("src") ||
                    "";

                seen[fullUrl] = true;

                results.push({
                    id: fullUrl,
                    title: title,
                    synonyms: [],
                    year: 1,
                    image: self.normalizeUrl(image),
                });

                self.storeMapping(fullUrl, title);
            });
        } catch (err) {
            console.error("hentaiera LoadDoc search parse failed: " + String(err));
        }

        var pattern = /<a[^>]+href=["']([^"']*\/gallery\/[0-9]+\/?[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
        var match;

        while ((match = pattern.exec(html)) !== null) {
            var href = this.decode(match[1] || "");
            var inner = match[2] || "";
            var fullUrl = this.normalizeGalleryUrl(href);

            if (!fullUrl || seen[fullUrl]) {
                continue;
            }

            var title =
                this.cleanSearchTitle(this.firstMatch(inner, /title=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /alt=["']([^"']+)["']/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /<h1[^>]*>([\s\S]*?)<\/h1>/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /<h2[^>]*>([\s\S]*?)<\/h2>/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /<h3[^>]*>([\s\S]*?)<\/h3>/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /<h4[^>]*>([\s\S]*?)<\/h4>/i)) ||
                this.cleanSearchTitle(this.firstMatch(inner, /class=["'][^"']*(?:gallery-title|post-title|entry-title|card-title|title|name|caption)[^"']*["'][^>]*>([\s\S]*?)<\/[^>]+>/i)) ||
                "";

            if (!title || this.titleLooksLikeTagBlob(title)) {
                title = this.titleFromUrl(fullUrl);
            }

            if (this.isBlockedText(title)) {
                continue;
            }

            var image =
                this.firstMatch(inner, /data-src=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /data-original=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /data-lazy-src=["']([^"']+)["']/i) ||
                this.firstMatch(inner, /src=["']([^"']+)["']/i) ||
                "";

            seen[fullUrl] = true;

            results.push({
                id: fullUrl,
                title: title,
                synonyms: [],
                year: 1,
                image: this.normalizeUrl(this.decode(image)),
            });

            this.storeMapping(fullUrl, title);
        }

        return results;
    }

    parseGalleryImages(html) {
        var candidates = [];
        var seenCandidate = {};
        var self = this;

        function addCandidate(raw) {
            var url = self.decode(String(raw || "").trim());

            if (!url) {
                return;
            }

            url = self.decodeEscapedUrl(url);

            if (url.indexOf(",") >= 0 && url.indexOf(" ") >= 0) {
                self.addSrcsetCandidates(url, addCandidate);
                return;
            }

            url = self.extractUrlFromStyle(url);
            url = self.normalizeUrl(url);

            if (!self.isHentaieraImage(url)) {
                return;
            }

            if (self.isCoverOrUiImage(url)) {
                return;
            }

            if (seenCandidate[url]) {
                return;
            }

            seenCandidate[url] = true;
            candidates.push(url);
        }

        try {
            var $ = LoadDoc(html);

            $("a[href], img, source, meta, div, span").each(function (i, e) {
                addCandidate(e.attr("href") || "");
                addCandidate(e.attr("content") || "");
                addCandidate(e.attr("data-src") || "");
                addCandidate(e.attr("data-original") || "");
                addCandidate(e.attr("data-lazy-src") || "");
                addCandidate(e.attr("data-full") || "");
                addCandidate(e.attr("data-url") || "");
                addCandidate(e.attr("data-large_image") || "");
                addCandidate(e.attr("data-large-file") || "");
                addCandidate(e.attr("data-bg") || "");
                addCandidate(e.attr("data-background") || "");
                addCandidate(e.attr("src") || "");
                addCandidate(e.attr("srcset") || "");
                addCandidate(e.attr("style") || "");
            });
        } catch (err) {
            console.error("hentaiera LoadDoc image parse failed: " + String(err));
        }

        var patterns = [
            /https?:\/\/m[0-9]+\.hentaiera\.com\/[^"'<>\s\\]+\.(?:jpg|jpeg|png|webp)(?:\?[^"'<>\s\\]*)?/gi,
            /\/\/m[0-9]+\.hentaiera\.com\/[^"'<>\s\\]+\.(?:jpg|jpeg|png|webp)(?:\?[^"'<>\s\\]*)?/gi,
            /https?:\\?\/\\?\/m[0-9]+\.hentaiera\.com\\?\/[^"'<>\\\s]+\.(?:jpg|jpeg|png|webp)(?:\\?[^"'<>\\\s]*)?/gi,
            /https?:\/\/[^"'<>\s\\]*hentaiera[^"'<>\s\\]*\/[^"'<>\s\\]+\.(?:jpg|jpeg|png|webp)(?:\?[^"'<>\s\\]*)?/gi,
            /https?:\\?\/\\?\/[^"'<>\\\s]*hentaiera[^"'<>\\\s]*\\?\/[^"'<>\\\s]+\.(?:jpg|jpeg|png|webp)(?:\\?[^"'<>\\\s]*)?/gi,
            /["']([^"']*\/wp-content\/uploads\/[^"']+\.(?:jpg|jpeg|png|webp)(?:\?[^"']*)?)["']/gi,
            /["']([^"']*\/uploads\/[^"']+\.(?:jpg|jpeg|png|webp)(?:\?[^"']*)?)["']/gi,
            /url\(([^)]+\.(?:jpg|jpeg|png|webp)(?:\?[^)]*)?)\)/gi
        ];

        for (var p = 0; p < patterns.length; p++) {
            var m;

            while ((m = patterns[p].exec(html)) !== null) {
                addCandidate(m[1] || m[0]);
            }
        }

        var pageCount = this.parsePageCount(html);
        var expanded = this.expandMissingGalleryImages(candidates, pageCount);

        for (var e = 0; e < expanded.length; e++) {
            if (!seenCandidate[expanded[e]]) {
                seenCandidate[expanded[e]] = true;
                candidates.push(expanded[e]);
            }
        }

        var grouped = {};
        var unnumbered = [];

        for (var i = 0; i < candidates.length; i++) {
            var img = candidates[i];
            var n = this.imageNumber(img);

            if (!n) {
                unnumbered.push(img);
                continue;
            }

            if (!grouped[n]) {
                grouped[n] = {
                    full: "",
                    thumb: "",
                    any: "",
                };
            }

            if (!grouped[n].any) {
                grouped[n].any = img;
            }

            if (this.isThumbImage(img)) {
                if (!grouped[n].thumb) {
                    grouped[n].thumb = img;
                }
            } else {
                if (!grouped[n].full) {
                    grouped[n].full = img;
                }
            }
        }

        var nums = [];

        for (var key in grouped) {
            nums.push(Number(key));
        }

        nums.sort(function (a, b) {
            return a - b;
        });

        var images = [];
        var seenFinal = {};

        for (var x = 0; x < nums.length; x++) {
            var group = grouped[nums[x]];
            var chosen = group.full || group.thumb || group.any;

            if (chosen && !seenFinal[chosen]) {
                seenFinal[chosen] = true;
                images.push(chosen);
            }
        }

        if (images.length === 0) {
            unnumbered.sort();

            for (var u = 0; u < unnumbered.length; u++) {
                if (!seenFinal[unnumbered[u]]) {
                    seenFinal[unnumbered[u]] = true;
                    images.push(unnumbered[u]);
                }
            }
        }

        console.log("hentaiera parsed pageCount=" + pageCount + " candidates=" + candidates.length + " final=" + images.length);

        return images;
    }

    parsePageCount(html) {
        var max = 0;
        var text = this.cleanText(html);

        var countPatterns = [
            /pages?\s*[:\-]?\s*([0-9]{1,4})/i,
            /([0-9]{1,4})\s*pages?/i,
            /page\s*1\s*of\s*([0-9]{1,4})/i,
            /read\s*now\s*for\s*free[\s\S]{0,80}?([0-9]{1,4})\s*pages?/i
        ];

        for (var i = 0; i < countPatterns.length; i++) {
            var m = text.match(countPatterns[i]);

            if (m && m[1]) {
                var n = Number(m[1]) || 0;

                if (n > max) {
                    max = n;
                }
            }
        }

        var htmlPatterns = [
            /\/([0-9]+)(?:t|-thumb)?\.(?:jpg|jpeg|png|webp)/gi,
            /page[-_]?([0-9]+)/gi,
            /data-page=["']?([0-9]+)["']?/gi
        ];

        for (var p = 0; p < htmlPatterns.length; p++) {
            var match;

            while ((match = htmlPatterns[p].exec(html)) !== null) {
                var num = Number(match[1] || 0);

                if (num > max) {
                    max = num;
                }
            }
        }

        return max;
    }

    expandMissingGalleryImages(candidates, pageCount) {
        var out = [];

        if (!pageCount || pageCount <= 0 || !candidates || candidates.length === 0) {
            return out;
        }

        var template = this.findBestImageTemplate(candidates);

        if (!template) {
            return out;
        }

        for (var i = 1; i <= pageCount; i++) {
            var url = this.applyImageTemplate(template, i);

            if (url) {
                out.push(url);
            }
        }

        return out;
    }

    findBestImageTemplate(candidates) {
        var best = "";

        for (var i = 0; i < candidates.length; i++) {
            var url = String(candidates[i] || "");

            if (!url) {
                continue;
            }

            if (!this.imageNumber(url)) {
                continue;
            }

            if (!this.isThumbImage(url)) {
                best = url;
                break;
            }

            if (!best) {
                best = url;
            }
        }

        return best;
    }

    applyImageTemplate(template, pageNumber) {
        var clean = String(template || "");

        if (!clean || !pageNumber) {
            return "";
        }

        var query = "";
        var qIndex = clean.indexOf("?");

        if (qIndex >= 0) {
            query = clean.slice(qIndex);
            clean = clean.slice(0, qIndex);
        }

        var replaced = clean.replace(/\/([0-9]+)(t|-thumb)?\.(jpg|jpeg|png|webp)$/i, function (all, oldNum, thumb, ext) {
            return "/" + pageNumber + (thumb || "") + "." + ext;
        });

        if (replaced === clean) {
            replaced = clean.replace(/\/page[-_]?([0-9]+)\.(jpg|jpeg|png|webp)$/i, function (all, oldNum, ext) {
                return "/page-" + pageNumber + "." + ext;
            });
        }

        if (replaced === clean) {
            return "";
        }

        return replaced + query;
    }

    extractUrlFromStyle(value) {
        var text = String(value || "").trim();

        if (!text) {
            return "";
        }

        var match = text.match(/url\(([^)]+)\)/i);

        if (match && match[1]) {
            return match[1].replace(/^["']|["']$/g, "");
        }

        return text;
    }

    addSrcsetCandidates(srcset, add) {
        var parts = String(srcset || "").split(",");

        for (var i = 0; i < parts.length; i++) {
            var part = parts[i].trim();
            var url = part.split(/\s+/)[0];

            if (url) {
                add(url);
            }
        }
    }

    imageNumber(url) {
        var clean = String(url || "").split("?")[0];

        var patterns = [
            /\/([0-9]+)(?:t|-thumb)?\.(jpg|jpeg|png|webp)$/i,
            /\/page[-_]?([0-9]+)\.(jpg|jpeg|png|webp)$/i,
            /\/([0-9]+)\/[^\/]+\.(jpg|jpeg|png|webp)$/i
        ];

        for (var i = 0; i < patterns.length; i++) {
            var match = clean.match(patterns[i]);

            if (match && match[1]) {
                return Number(match[1]) || 0;
            }
        }

        return 0;
    }

    isThumbImage(url) {
        var clean = String(url || "").split("?")[0].toLowerCase();

        return (
            /\/[0-9]+t\.(jpg|jpeg|png|webp)$/i.test(clean) ||
            clean.indexOf("-thumb.") >= 0 ||
            clean.indexOf("thumbnail") >= 0 ||
            clean.indexOf("/thumb") >= 0
        );
    }

    isCoverOrUiImage(url) {
        var lower = String(url || "").toLowerCase();

        if (lower.match(/\/cover\.(jpg|jpeg|png|webp)(?:\?|$)/i)) {
            return true;
        }

        return (
            lower.indexOf("logo") >= 0 ||
            lower.indexOf("avatar") >= 0 ||
            lower.indexOf("banner") >= 0 ||
            lower.indexOf("favicon") >= 0 ||
            lower.indexOf("sprite") >= 0 ||
            lower.indexOf("icon") >= 0 ||
            lower.indexOf("placeholder") >= 0 ||
            lower.indexOf("loading") >= 0 ||
            lower.indexOf("advert") >= 0 ||
            lower.indexOf("/ads/") >= 0
        );
    }

    isHentaieraImage(url) {
        var lower = String(url || "").toLowerCase();

        if (lower.indexOf("http") !== 0) {
            return false;
        }

        if (
            lower.indexOf(".jpg") < 0 &&
            lower.indexOf(".jpeg") < 0 &&
            lower.indexOf(".png") < 0 &&
            lower.indexOf(".webp") < 0
        ) {
            return false;
        }

        if (
            lower.indexOf("hentaiera.com") < 0 &&
            lower.indexOf("hentaiera.") < 0 &&
            lower.indexOf("/wp-content/uploads/") < 0 &&
            lower.indexOf("/uploads/") < 0
        ) {
            return false;
        }

        return true;
    }

    searchScore(query, title, url) {
        var q = this.cleanComparable(query);
        var t = this.cleanComparable(title);

        if (!q || !t) {
            return 0;
        }

        if (this.titleLooksLikeTagBlob(title)) {
            return 0;
        }

        var score = 0;

        if (t === q) {
            score += 120;
        }

        if (t.indexOf(q) >= 0) {
            score += 90;
        }

        if (q.indexOf(t) >= 0 && t.length >= 4) {
            score += 55;
        }

        var qWords = q.split(" ");
        var tWords = t.split(" ");

        var hits = 0;
        var strongHits = 0;
        var missingStrongWords = 0;

        for (var i = 0; i < qWords.length; i++) {
            var word = qWords[i];

            if (!word || word.length < 2) {
                continue;
            }

            if (this.arrayContainsWord(tWords, word)) {
                hits++;

                if (word.length >= 4) {
                    strongHits++;
                }
            } else if (word.length >= 4) {
                missingStrongWords++;
            }
        }

        if (qWords.length > 0) {
            score += Math.round((hits / qWords.length) * 55);
        }

        score += strongHits * 10;
        score -= missingStrongWords * 20;

        if (qWords.length >= 2 && hits < Math.ceil(qWords.length * 0.55)) {
            score -= 50;
        }

        if (String(title || "").length > 160) {
            score -= 35;
        }

        return score;
    }

    arrayContainsWord(words, target) {
        for (var i = 0; i < words.length; i++) {
            if (words[i] === target) {
                return true;
            }
        }

        return false;
