    getGalleryTitle(html, url) {
        var title =
            this.cleanText(this.firstMatch(html, /<h1[^>]*>([\s\S]*?)<\/h1>/i)) ||
            this.cleanText(this.firstMatch(html, /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i)) ||
            this.cleanText(this.firstMatch(html, /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i)) ||
            this.cleanText(this.firstMatch(html, /<title[^>]*>([\s\S]*?)<\/title>/i)) ||
            this.titleFromUrl(url);

        title = title
            .replace(/\s*-\s*HentaiEra\s*$/i, "")
            .replace(/\s*\|\s*HentaiEra\s*$/i, "")
            .replace(/\s*HentaiEra\s*$/i, "")
            .replace(/\s*Read Now.*$/i, "")
            .replace(/\s*Free.*$/i, "")
            .trim();

        return this.decode(title);
