    getGalleryLanguage(html) {
        var cleaned = this.cleanText(html).toLowerCase();

        if (cleaned.indexOf(" english ") >= 0) return "en";
        if (cleaned.indexOf(" japanese ") >= 0) return "ja";
        if (cleaned.indexOf(" spanish ") >= 0) return "es";
        if (cleaned.indexOf(" french ") >= 0) return "fr";
        if (cleaned.indexOf(" korean ") >= 0) return "ko";
        if (cleaned.indexOf(" german ") >= 0) return "de";
        if (cleaned.indexOf(" russian ") >= 0) return "ru";
        if (cleaned.indexOf(" portuguese ") >= 0) return "pt";
        if (cleaned.indexOf(" chinese ") >= 0) return "zh";

        var langMatch = String(html || "").match(/\/language\/([^"'/]+)[^"']*["'][^>]*>([\s\S]*?)<\/a>/i);

        if (langMatch && langMatch[2]) {
            var lang = this.cleanText(langMatch[2]).toLowerCase();

            if (lang.indexOf("english") >= 0) return "en";
            if (lang.indexOf("japanese") >= 0) return "ja";
            if (lang.indexOf("spanish") >= 0) return "es";
            if (lang.indexOf("french") >= 0) return "fr";
            if (lang.indexOf("korean") >= 0) return "ko";
            if (lang.indexOf("german") >= 0) return "de";
            if (lang.indexOf("russian") >= 0) return "ru";
            if (lang.indexOf("portuguese") >= 0) return "pt";
            if (lang.indexOf("chinese") >= 0) return "zh";
        }

        return "en";
    }

    getSynonymsFromGallery(html) {
        var out = [];
        var seen = {};
        var pattern = /\/(?:tag|artist|parody|character|group|category|language)\/[^"']+["'][^>]*>([\s\S]*?)<\/a>/gi;
        var match;

        while ((match = pattern.exec(html)) !== null) {
            var text = this.cleanText(match[1] || "");

            if (!text || seen[text]) {
                continue;
            }

            seen[text] = true;
            out.push(text);
        }

        return out;
    }

    hasBlockedTags(html) {
        var text = this.cleanText(html);
        return this.isBlockedText(text);
