    isBlockedText(input) {
        var t = String(input || "").toLowerCase();

        return (
            t.indexOf("lolicon") >= 0 ||
            t.indexOf("shotacon") >= 0 ||
            t.indexOf("shota") >= 0 ||
            t.indexOf("loli") >= 0 ||
            t.indexOf("underage") >= 0 ||
            t.indexOf("minor") >= 0 ||
            t.indexOf("child") >= 0 ||
            t.indexOf("children") >= 0
        );
    }

    lookupStoredUrl(input) {
        var key = String(input || "").trim();

        if (!key) {
            return "";
        }

        var map = this.getProviderMap();

        if (map.byInput && map.byInput[key]) {
            return map.byInput[key];
        }

        if (map.byId && map.byId[key]) {
            return map.byId[key];
        }

        var clean = this.cleanComparable(key);

        if (map.byTitle && map.byTitle[clean]) {
            return map.byTitle[clean];
        }

        try {
            if (typeof $store !== "undefined") {
                var customMap = $store.get(this.customSourceMapKey) || {};

                if (customMap[key]) {
                    return customMap[key];
                }

                if (customMap[Number(key)]) {
                    return customMap[Number(key)];
                }
            }
        } catch (err) {
        }

        return "";
    }

    lookupTitleUrl(title) {
        var clean = this.cleanComparable(title);

        if (!clean) {
            return "";
        }

        var map = this.getProviderMap();

        if (map.byTitle && map.byTitle[clean]) {
            return map.byTitle[clean];
        }

        return "";
    }

    storeMapping(url, title) {
        url = this.normalizeGalleryUrl(url);

        if (!url) {
            return;
        }

        var map = this.getProviderMap();

        if (!map.byId) map.byId = {};
        if (!map.byTitle) map.byTitle = {};
        if (!map.byInput) map.byInput = {};

        var id = this.getGalleryId(url);

        if (id) {
            map.byId[id] = url;
        }

        map.byInput[url] = url;

        if (title) {
            map.byTitle[this.cleanComparable(title)] = url;
        }

        this.setProviderMap(map);
    }

    getProviderMap() {
        if (this.cache.__providerMap) {
            return this.cache.__providerMap;
        }

        var map = {
            byId: {},
            byTitle: {},
            byInput: {},
        };

        try {
            if (typeof $store !== "undefined") {
                var stored = $store.get(this.providerMapKey);

                if (stored) {
                    map = stored;
                }
            }
        } catch (err) {
        }

        if (!map.byId) map.byId = {};
        if (!map.byTitle) map.byTitle = {};
        if (!map.byInput) map.byInput = {};

        this.cache.__providerMap = map;

        return map;
    }

    setProviderMap(map) {
        this.cache.__providerMap = map;

        try {
            if (typeof $store !== "undefined") {
                $store.set(this.providerMapKey, map);
            }
        } catch (err) {
        }
    }

    normalizeGalleryUrl(input) {
        var url = this.normalizeUrl(input);

        if (!url) {
            return "";
        }

        var id = this.getGalleryId(url);

        if (!id) {
            return "";
        }

        return this.api + "/gallery/" + id + "/";
    }

    normalizeUrl(input) {
        var url = this.decode(String(input || "").trim());

        if (!url) {
            return "";
        }

        url = this.decodeEscapedUrl(url);

        if (url.indexOf("//") === 0) {
            return "https:" + url;
        }

        if (url.indexOf("/") === 0) {
            return this.api + url;
        }

        if (url.indexOf("http") === 0) {
            return url;
        }

        return this.api + "/" + url;
    }

    decodeEscapedUrl(url) {
        return String(url || "")
            .replace(/&amp;/g, "&")
            .replace(/\\u0026/g, "&")
            .replace(/\\u003d/g, "=")
            .replace(/\\u003D/g, "=")
            .replace(/\\u003f/g, "?")
            .replace(/\\u003F/g, "?")
            .replace(/\\u003a/g, ":")
            .replace(/\\u003A/g, ":")
            .replace(/\\u002f/g, "/")
            .replace(/\\u002F/g, "/")
            .replace(/\\\//g, "/")
            .replace(/&quot;/g, "\"");
    }

    getGalleryId(input) {
        var text = String(input || "").trim();

        var patterns = [
            /hentaiera\.com\/gallery\/([0-9]+)/i,
            /\/gallery\/([0-9]+)/i,
            /^([0-9]+)$/
        ];

        for (var i = 0; i < patterns.length; i++) {
            var match = text.match(patterns[i]);

            if (match && match[1]) {
                return match[1];
            }
        }

        return "";
    }

    looksLikeGalleryId(id) {
        var text = String(id || "");

        if (!text.match(/^[0-9]+$/)) {
            return false;
        }

        return text.length >= 4 && text.length <= 8;
    }

    titleFromUrl(url) {
        var id = this.getGalleryId(url);

        if (id) {
            return "HentaiEra " + id;
        }

        return "HentaiEra Gallery";
    }

    titleLooksRelevant(query, title) {
        return this.searchScore(query, title, "") >= 40;
    }

    slugify(input) {
        return String(input || "")
            .toLowerCase()
            .replace(/&/g, " and ")
            .replace(/['’]/g, "")
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-+|-+$/g, "");
    }

    cleanComparable(input) {
        return String(input || "")
            .toLowerCase()
            .replace(/\[[^\]]+\]/g, " ")
            .replace(/\([^\)]*\)/g, " ")
            .replace(/[^a-z0-9]+/g, " ")
            .replace(/\s+/g, " ")
            .trim();
    }

    cleanSearchTitle(input) {
        var text = this.cleanText(input);

        text = text
            .replace(/\s+/g, " ")
            .replace(/\s*new\s*$/i, "")
            .replace(/\s*read now.*$/i, "")
            .replace(/\s*comments?.*$/i, "")
            .replace(/\s*pages?.*$/i, "")
            .replace(/\s*artist.*$/i, "")
            .replace(/\s*parody.*$/i, "")
            .replace(/\s*character.*$/i, "")
            .replace(/\s*category.*$/i, "")
            .replace(/\s*language.*$/i, "")
            .replace(/\s*tags?.*$/i, "")
            .trim();

        if (text.length > 140) {
            text = text.slice(0, 140).trim();
        }

        return text;
    }

    async fetchText(url) {
        var cached = this.cache[url];

        if (cached && cached.expires > Date.now()) {
            return cached.text;
        }

        var res = await fetch(url, {
            headers: {
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
                "User-Agent": "Mozilla/5.0",
                "Referer": this.api + "/",
            },
        });

        if (!res.ok) {
            throw new Error("HTTP " + res.status + " for " + url);
        }

        var text = await res.text();

        this.cache[url] = {
            text: text,
            expires: Date.now() + 5 * 60 * 1000,
        };

        return text;
    }

    firstMatch(text, pattern) {
        var match = String(text || "").match(pattern);
        return match && match[1] ? match[1] : "";
    }

    cleanText(input) {
        return this.decode(
            String(input || "")
                .replace(/<script[\s\S]*?<\/script>/gi, " ")
                .replace(/<style[\s\S]*?<\/style>/gi, " ")
                .replace(/<[^>]+>/g, " ")
                .replace(/\s+/g, " ")
                .trim()
        );
    }

    decode(input) {
        return String(input || "")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, "\"")
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&#x2F;/g, "/")
            .replace(/&#47;/g, "/")
            .replace(/&nbsp;/g, " ");
    }
